9	import {
10	  registrarConfigured,
11	  registrarSafeMessage,
12	  checkDomains,
13	  registerDomain,
14	  renewDomain,
15	  domainInfo,
16	  listRecords,
17	  addRecord,
18	  deleteRecord,
19	  type RegistrantContact,
20	} from "./registrar";
