37	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
38	
39	function errMsg(e: unknown): string {
40	  return registrarSafeMessage(e);
41	}
42	
43	function fmtExpiry(d: Date): string {
44	  return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
45	}
