47	/**
48	 * Domain lifecycle emails — emails.domainRegistered/domainRenewed have
49	 * existed in lib/email-templates.ts since the catalog was built, but nothing
50	 * ever actually called them, so a real domain purchase or renewal produced
51	 * only an in-app notification (invisible unless the customer happens to be
52	 * signed in and checks the bell) and no email at all. Fire-and-forget, same
53	 * shape as requestPasswordReset's send in lib/actions-account.ts: never
54	 * awaited, never lets a mail hiccup affect the response. `sendMail` itself
55	 * gates on the customer's notification preferences when given `kind` +
56	 * `userId` (see lib/mailer.ts) — domain_activity is ACCOUNT-tier, not
57	 * CRITICAL, so it's suppressible, unlike a password reset.
58	 */
59	function sendDomainRegisteredEmail(userId: string, domain: string, expiresAt: Date): void {
60	  void (async () => {
61	    const user = await db.user.findUnique({ where: { id: userId }, select: { email: true } });
62	    if (!user) return;
63	    const tpl = emails.domainRegistered({ domain, expiryDate: fmtExpiry(expiresAt) });
64	    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId, kind: "domain_activity" });
65	  })().catch((e) => {
66	    console.error("[domain-registered-email] send failed:", e);
67	  });
68	}
69	
70	function sendDomainRenewedEmail(userId: string, domain: string, expiresAt: Date): void {
71	  void (async () => {
72	    const user = await db.user.findUnique({ where: { id: userId }, select: { email: true } });
73	    if (!user) return;
74	    const tpl = emails.domainRenewed({ domain, expiryDate: fmtExpiry(expiresAt) });
75	    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId, kind: "domain_activity" });
76	  })().catch((e) => {
77	    console.error("[domain-renewed-email] send failed:", e);
78	  });
79	}
