81	/* ------------------------------------------------------------------ *
82	 * Idempotency helpers
83	 *
84	 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
85	 * user+domain. Catches the double-click / impatient-retry case immediately and
86	 * keeps two concurrent requests from both reaching the registrar. Best-effort
87	 * only — it does not survive a restart or span multiple app instances.
88	 *
89	 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
90	 * charge+create runs in one `$transaction`, so a duplicate can never both take
91	 * money and create a second row. Renewal is guarded by an in-transaction expiry
92	 * re-check (charge and expiry advance together atomically).
93	 * ------------------------------------------------------------------ */
94	
95	const SUBMIT_GUARD_MS = 120_000;
96	const inFlightSubmits = new Map<string, number>();
97	
98	function beginSubmit(key: string): boolean {
99	  const now = Date.now();
100	  const heldUntil = inFlightSubmits.get(key);
101	  if (heldUntil !== undefined && heldUntil > now) return false;
102	  if (inFlightSubmits.size > 2000) {
103	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
104	  }
105	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
106	  return true;
107	}
108	
109	function endSubmit(key: string): void {
110	  inFlightSubmits.delete(key);
111	}
112	
113	class DuplicateDomainError extends Error {
114	  constructor() {
115	    super("DUPLICATE_DOMAIN");
116	    this.name = "DuplicateDomainError";
117	  }
118	}
119	
120	const isUniqueConflict = (e: any) => e?.code === "P2002";
121	
122	type RegistrationVerdict = { state: "registered" | "not-registered" | "unknown"; expires?: Date };
123	
124	/**
125	 * After a registrar call fails or times out we must NOT assume the registration
126	 * did not happen — name.com may well have taken the order. Ask the registrar
127	 * before touching the customer's money:
128	 *  - the domain is in our reseller account  -> registered (keep the charge)
129	 *  - the domain is still purchasable        -> not registered (safe to refund)
130	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
131	 */
132	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
133	  try {
134	    const info = await domainInfo(domain);
135	    return { state: "registered", expires: info.expires };
136	  } catch {
137	    /* not in our account, or the API is unhappy — fall through to availability */
138	  }
139	  try {
140	    const [check] = await checkDomains([domain]);
141	    if (check?.available === true) return { state: "not-registered" };
142	  } catch {
143	    /* registrar unreachable */
144	  }
145	  return { state: "unknown" };
146	}
147	
148	/**
149	 * Raised by `registerDomainCore` for anything that stops BEFORE a `Domain` row
150	 * exists (duplicate name, insufficient balance) — the caller shows `e.message`
151	 * verbatim, exactly like the inline `return { error }`s this replaced.
152	 */
153	class DomainOrderError extends Error {}
154	
155	/**
156	 * What actually happened once a `Domain` row was created and the registrar was
157	 * called — the three-way outcome `purchaseDomain` always had, now a return
158	 * value instead of being baked into one function's control flow, so both the
159	 * wallet path and the card-fulfilment path can react to it identically.
160	 */
161	type DomainRegistrationResult =
162	  | { kind: "active"; domainId: string }
163	  | { kind: "refunded"; domainId: string; message: string }
164	  | { kind: "needs-review"; domainId: string; message: string };
165	
166	/**
167	 * The registrar call + wallet debit + `Domain` row create/update + verify-on-
168	 * failure + `setupDomainInboxEmail` — extracted verbatim from `purchaseDomain`
169	 * so BOTH the direct-wallet action below and the card-fulfilment path
170	 * (`placeDomainCardOrder`) run the exact same money-and-registrar logic against
171	 * a FROZEN `priced` (never a fresh `checkDomains` re-quote taken here — the
172	 * caller already fetched it, at session-creation time for the card path, and
173	 * that is the one and only quote this purchase is ever priced against).
174	 *
175	 * Deliberately UNEXPORTED (this file has `"use server"`, so every export
176	 * becomes a client-invokable Server Action). `user` is trusted completely —
177	 * its `id` and `balanceCents` drive a real wallet debit — so this must only
178	 * ever be reachable from a caller that already resolved `user` itself
179	 * (`purchaseDomain`'s `requireUser()`, or `placeDomainCardOrder`'s verified
180	 * Stripe session), never from a client-suppliable argument. Same reasoning as
181	 * `orderEmailHostingCore` staying unexported in lib/actions-email-hosting.ts
182	 * (see lib/domain-inbox-email.ts's header comment).
183	 */
184	async function registerDomainCore(
185	  user: User,
186	  params: {
187	    domain: string;
188	    years: number;
189	    contact: RegistrantContact;
190	    mailboxLocalPart: string | null;
191	    partnerSource: string | null;
192	  },
193	  priced: DomainOrderPrice,
194	): Promise<DomainRegistrationResult> {
195	  const { domain, contact, mailboxLocalPart, partnerSource } = params;
196	  const dTerm = domainTerm(params.years);
197	  const totalCents = domainTermPriceCents(priced.priceCents, dTerm.years);
198	  const registrarCostCents = priced.costCents * dTerm.years;
199	
200	  const existing = await db.domain.findUnique({ where: { name: domain } });
201	  if (existing) {
202	    if (existing.userId !== user.id) throw new DomainOrderError("This domain is already managed by another account.");
203	    if (existing.status === "PENDING") {
204	      throw new DomainOrderError("You already have a registration in progress for this domain.");
205	    }
206	    // FAILED = a previous attempt never actually registered anything and was
207	    // already refunded — see purchaseDomain's identical carve-out above for
208	    // why this must not permanently block a retry. Every other status still
209	    // does (ACTIVE/EXPIRED/TRANSFER_* all mean something real exists here).
210	    if (existing.status !== "FAILED") {
211	      throw new DomainOrderError(`You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).`);
212	    }
213	  }
214	
215	  if (user.balanceCents < totalCents) {
216	    throw new DomainOrderError(`Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.`);
217	  }
218	
219	  let record;
220	  try {
221	    record = await db.$transaction(async (tx) => {
222	      // Re-check inside the transaction: the availability round-trip above is
223	      // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
224	      // even if this read misses, the create below rolls the whole debit back.
225	      const dupe = await tx.domain.findUnique({ where: { name: domain } });
226	      if (dupe) {
227	        if (dupe.userId !== user.id || dupe.status !== "FAILED") throw new DuplicateDomainError();
228	        // Clear the stale FAILED row so the create below doesn't collide with
229	        // the UNIQUE constraint on `name` — safe: it belongs to this same
230	        // user and holds no real registration (confirmed just above too;
231	        // this is the transaction-safe re-check for the retry race).
232	        await tx.domain.delete({ where: { id: dupe.id } });
233	      }
234	      await debitWallet(tx, user.id, totalCents);
235	      await tx.walletTransaction.create({
236	        data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
237	      });
238	      return tx.domain.create({
239	        data: {
240	          name: domain,
241	          userId: user.id,
242	          priceCents: priced.priceCents,
243	          costCents: priced.costCents,
244	          termYears: dTerm.years,
245	          status: "PENDING",
246	          registrar: "name.com",
247	          partnerSource: partnerSource ?? null,
248	          // renewPriceCents/renewCostCents: freeze the SAME registrar quote's
249	          // renewal price so a later renewal charges what was shown at
250	          // checkout, not the (possibly stale) first-year price — see
251	          // Domain.renewPriceCents's doc comment in schema.prisma. `as any`
252	          // below is because this worktree deliberately has NOT regenerated
253	          // the (shared, live-symlinked) Prisma Client against these new,
254	          // not-yet-pushed columns — see that same doc comment for why. Safe
255	          // no-op until `prisma db push` + `generate` run for real; drop the
256	          // cast then.
257	          renewPriceCents: priced.renewPriceCents ?? null,
258	          renewCostCents: priced.renewCostCents ?? null,
259	        } as any,
260	      });
261	    });
262	  } catch (e) {
263	    if (e instanceof InsufficientBalanceError) throw new DomainOrderError("Insufficient balance — top up your wallet first.");
264	    if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
265	      throw new DomainOrderError("This domain is already being registered — you have not been charged twice.");
266	    }
267	    throw e;
268	  }
269	
270	  try {
271	    const { expiresAt } = await registerDomain(domain, dTerm.years, contact, registrarCostCents);
272	    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
273	    await db.domain.update({
274	      where: { id: record.id },
275	      data: {
276	        status: "ACTIVE",
277	        registeredAt: new Date(),
278	        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
279	      },
280	    });
281	    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
282	    await db.notification.create({
283	      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
284	    });
285	    // Tell the partner (best-effort, never blocks the order) — only for orders
286	    // tagged via a partner deep link. Most domain registrations are direct Nxeon
287	    // customers and must never be forwarded to a partner's webhook.
288	    if (partnerSource === "kodely") {
289	      await notifyPartner("domain.registered", { userId: user.id, domain, expiresAt: info.expires ?? null });
290	    }
291	    // Every domain registered through Nxeon includes a free inbox — see
292	    // lib/domain-inbox-email.ts. Best-effort: never lets a mailbox hiccup
293	    // undo a domain purchase that already succeeded.
294	    await setupDomainInboxEmail({
295	      userId: user.id,
296	      domainName: domain,
297	      expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
298	      mailboxLocalPart,
299	    });
300	    sendDomainRegisteredEmail(user.id, domain, info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000));
301	    return { kind: "active", domainId: record.id };
302	  } catch (e: any) {
303	    // `reason` is RAW (kept for the audit trail below — admin-only). Anything
304	    // that ends up on `Domain.error` or in a returned `message`, on the other
305	    // hand, reaches the customer directly (the FAILED banner on the domain
306	    // page, and lib/kb-tools.ts's AI chat context) — those use `customerReason`
307	    // instead, which is registrar-name-free by construction when `e` is a
308	    // `RegistrarError`.
309	    const reason = String(e?.message ?? e).slice(0, 400);
310	    const customerReason = errMsg(e);
311	    // NEVER refund blind: a timeout/5xx often means the order DID go through.
312	    const verdict = await verifyRegistration(domain);
313	
314	    if (verdict.state === "registered") {
315	      // The registration exists — keep the charge and finish the record.
316	      await db.domain.update({
317	        where: { id: record.id },
318	        data: {
319	          status: "ACTIVE",
320	          registeredAt: new Date(),
321	          expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
322	          error: `Recovered after a registration issue: ${customerReason}`.slice(0, 500),
323	        },
324	      });
325	      await db.auditLog.create({
326	        data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
327	      });
328	      await db.notification.create({
329	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
330	      });
331	      // Recovered-but-registered still counts as a successful registration —
332	      // it gets the same free inbox the happy path does.
333	      await setupDomainInboxEmail({
334	        userId: user.id,
335	        domainName: domain,
336	        expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
337	        mailboxLocalPart,
338	      });
339	      sendDomainRegisteredEmail(user.id, domain, verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000));
340	      return { kind: "active", domainId: record.id };
341	    }
342	
343	    if (verdict.state === "not-registered") {
344	      // Confirmed still available at the registrar — refunding is safe.
345	      await db.$transaction([
346	        db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
347	        db.walletTransaction.create({
348	          data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
349	        }),
350	        db.domain.update({
351	          where: { id: record.id },
352	          data: { status: "FAILED", error: customerReason.slice(0, 500) },
353	        }),
354	      ]);
355	      // The raw (possibly registrar-attributed) reason goes here, not on
356	      // Domain.error — matching the "recovered"/"needs_review" branches above,
357	      // which log it the same way. Without this, the only place the real
358	      // diagnostic ever lands is an ephemeral server console line
359	      // (registrarSafeMessage's own console.error), which is far less
360	      // discoverable for ops later than a normal audit-log entry.
361	      await db.auditLog.create({
362	        data: { userId: user.id, action: "domain.register.failed", detail: `${domain}: ${reason}`.slice(0, 500) },
363	      });
364	      return {
365	        kind: "refunded",
366	        domainId: record.id,
367	        message: `Registration failed: ${customerReason.slice(0, 200)} (you were refunded).`,
368	      };
369	    }
370	
371	    // Unknown: leave PENDING and charged, flag for manual review. Refunding
372	    // here risks giving away a domain we actually paid the registrar for.
373	    await db.domain.update({
374	      where: { id: record.id },
375	      data: { status: "PENDING", error: `NEEDS REVIEW — registration status unconfirmed: ${customerReason}`.slice(0, 500) },
376	    });
377	    await db.auditLog.create({
378	      data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
379	    });
380	    await db.notification.create({
381	      data: {
382	        userId: user.id,
383	        title: `Domain ${domain} needs review`,
384	        body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
385	        href: `/dashboard/domains/${record.id}`,
386	      },
387	    });
388	    return {
389	      kind: "needs-review",
390	      domainId: record.id,
391	      message:
392	        `We could not confirm ${domain} (${customerReason.slice(0, 120)}). ` +
393	        `It is marked for review — do not retry, you will not be charged twice.`,
394	    };
395	  }
396	}
