398	export async function purchaseDomain(
399	  prev: any,
400	  formData: FormData,
401	): Promise<{ error?: string; checkout?: { clientSecret: string; publishableKey: string } }> {
402	  // Spend path: registering a domain debits the wallet AND buys a non-refundable
403	  // asset from a registrar in the customer's name, with registrant contact details
404	  // taken from this form. `submitTransferIn` — the same product, the same money —
405	  // has carried this guard since it was written; registration and renewal never did.
406	  await assertNotImpersonating();
407	  const user = await requireUser();
408	  // Purchase gate: an unverified address means we cannot reach the person we
409	  // are about to charge. See lib/email-verification.ts.
410	  const unverified = await emailVerificationError(user);
411	  if (unverified) return { error: unverified };
412	  // Feature flag: domain registration can be switched off platform-wide.
413	  if (!(await getSettingBool("feature_domains", true))) {
414	    return { error: "Domain registration is currently unavailable." };
415	  }
416	  if (!registrarConfigured()) {
417	    return { error: "Domain registration is not configured yet." };
418	  }
419	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
420	  // /dashboard/domains, captured into a cookie by PartnerSourceCapture). Read
421	  // synchronously here (unlike the VPS path, domain purchase is a same-request
422	  // wallet debit — no Stripe checkout/webhook race to round-trip through).
423	  const partnerSource = partnerSourceFromCookie(await cookies());
424	  const contactSchema = z.object({
425	    firstName: z.string().min(1).max(60),
426	    lastName: z.string().min(1).max(60),
427	    address1: z.string().min(1).max(120),
428	    city: z.string().min(1).max(60),
429	    stateProvince: z.string().min(1).max(60),
430	    postalCode: z.string().min(1).max(20),
431	    country: z.string().length(2),
432	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
433	    email: z.string().email(),
434	  });
435	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
436	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
437	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
438	  // Free Domain Inbox — the mailbox local-part the customer optionally chose
439	  // during registration (components/customer/DomainRegisterWizard.tsx's Email
440	  // step). Empty is valid: the inbox is still reserved, just mailbox-less
441	  // until they add one from /dashboard/email. See lib/domain-inbox-email.ts.
442	  const mailboxLocalPart = String(formData.get("mailboxLocalPart") ?? "").trim().toLowerCase() || null;
443	
444	  const contactParsed = contactSchema.safeParse({
445	    firstName: formData.get("firstName"),
446	    lastName: formData.get("lastName"),
447	    address1: formData.get("address1"),
448	    city: formData.get("city"),
449	    stateProvince: formData.get("stateProvince"),
450	    postalCode: formData.get("postalCode"),
451	    country: String(formData.get("country") ?? "").toUpperCase(),
452	    phone: formData.get("phone"),
453	    email: formData.get("email"),
454	  });
455	  if (!contactParsed.success) {
456	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
457	  }
458	  const contact = contactParsed.data as RegistrantContact;
459	
460	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
461	  // Also covers the card-shortfall branch below: that call only OPENS a Stripe
462	  // session (it doesn't touch the wallet or the registrar yet), so holding the
463	  // same guard just stops a double-click from opening two sessions for once
464	  // domain — it never blocks the SEPARATE call that later fulfils the paid one.
465	  const guardKey = `register:${user.id}:${domain}`;
466	  if (!beginSubmit(guardKey)) {
467	    return { error: "That registration is already being processed — give it a moment before retrying." };
468	  }
469	
470	  try {
471	    const existing = await db.domain.findUnique({ where: { name: domain } });
472	    if (existing) {
473	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
474	      if (existing.status === "PENDING") {
475	        return { error: "You already have a registration in progress for this domain." };
476	      }
477	      // FAILED means the earlier attempt never actually registered anything
478	      // and was already refunded (see the FAILED branch below/in
479	      // registerDomainCore) — nothing is owned under this name, so blocking a
480	      // retry here would contradict the platform's own promise ("you're never
481	      // charged for a name you don't get"). Real bug found live: a customer
482	      // hit a one-time registrar failure and then could never try that exact
483	      // domain again. Every other terminal status still blocks.
484	      if (existing.status !== "FAILED") {
485	        return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
486	      }
487	    }
488	
489	    // Live availability + retail(markup) & cost prices from name.com
490	    let priceCents: number; // retail per year (customer)
491	    let costCents: number; // registrar cost per year (us)
492	    // Renewal price/year, frozen from this SAME quote (see registerDomainCore's
493	    // Domain.create — `null` when the registrar had no distinct renewal price).
494	    let renewPriceCents: number | null;
495	    let renewCostCents: number | null;
496	    try {
497	      const [check] = await checkDomains([domain]);
498	      if (!check) return { error: "Could not check availability. Try again." };
499	      if (!check.available) return { error: "Domain is not available." };
500	      if (check.premium) return { error: "Premium domains are not supported yet." };
501	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
502	      priceCents = check.priceCents;
503	      costCents = check.costCents;
504	      renewPriceCents = check.renewCents;
505	      // The registrar client only reports a RETAIL renewal price; back out the
506	      // pre-markup cost the same way `costCents` already is one, so a future
507	      // renewal can tell the registrar what it expects to pay.
508	      renewCostCents = check.renewCents !== null && check.priceCents > 0 ? Math.round((check.renewCents * check.costCents) / check.priceCents) : null;
509	    } catch (e: any) {
510	      return { error: errMsg(e) };
511	    }
512	
513	    const totalCents = domainTermPriceCents(priceCents, dTerm.years);
514	    // Whether the customer opted to apply wallet balance at all (the wizard's
515	    // Review-step toggle, same one DeployWizard.tsx has always had) — real gap
516	    // found live: this was hardcoded `true` with no way for a customer to
517	    // choose card instead when the wallet already covered the total.
518	    const useWallet = formData.get("useWallet") !== "0";
519	    // Same split math every other card-funded purchase on this platform uses
520	    // (lib/wallet-split.ts) — NOT a bare `totalCents - balanceCents`. That naive
521	    // subtraction can land a 1–49c remainder on the card, which Stripe rejects
522	    // outright; `walletSplit` either clamps the card leg up to its 50c floor
523	    // (taking a touch less wallet) or, if the WHOLE total is under the floor,
524	    // drops the card leg entirely so the wallet is the only leg (surfaced below
525	    // by `cardCents <= 0` falling through to the direct-wallet path, which does
526	    // its own honest "Insufficient balance" check rather than a raw Stripe error).
527	    const { cardCents } = walletSplit({ dueCents: totalCents, balanceCents: user.balanceCents, useWallet });
528	
529	    if (cardCents > 0) {
530	      // Wallet doesn't cover it — open the embedded Payment step for the
531	      // SHORTFALL, mirroring payAndDeploy's wallet+card split (lib/actions.ts).
532	      // Nothing is charged or registered here; the actual registration only
533	      // happens once the card clears, via placeDomainCardOrder below.
534	      if (!stripeConfigured()) {
535	        return {
536	          error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}, and card payments aren't set up on this platform yet. Top up your wallet to continue.`,
537	        };
538	      }
539	      const priced: DomainOrderPrice = { priceCents, costCents, renewPriceCents, renewCostCents };
540	      // Stash the registrant contact + frozen price BEFORE opening the session —
541	      // see DomainOrderIntent's doc comment in schema.prisma for why this can't
542	      // just ride in Stripe metadata like a VPS/hosting/email order's intent
543	      // does (a registrant contact has no combined length cap that fits
544	      // Stripe's 500-char-per-value limit).
545	      const stashed = await db.domainOrderIntent.create({
546	        data: {
547	          userId: user.id,
548	          domain,
549	          years: dTerm.years,
550	          firstName: contact.firstName,
551	          lastName: contact.lastName,
552	          address1: contact.address1,
553	          city: contact.city,
554	          stateProvince: contact.stateProvince,
555	          postalCode: contact.postalCode,
556	          country: contact.country,
557	          phone: contact.phone,
558	          email: contact.email,
559	          mailboxLocalPart,
560	          partnerSource: partnerSource ?? null,
561	          priceCents,
562	          costCents,
563	          // See DomainOrderIntent.renewPriceCents's doc comment in schema.prisma
564	          // for the `as any` — not yet pushed to the live DB from this worktree.
565	          renewPriceCents,
566	          renewCostCents,
567	        } as any,
568	      });
569	      let checkout;
570	      try {
571	        checkout = await createDomainOrderPaymentSession(user, cardCents, domain, dTerm.years, stashed.id, priced);
572	      } catch (e: any) {
573	        return { error: String(e?.message ?? e).slice(0, 200) };
574	      }
575	      if (!checkout) {
576	        return { error: "Card payments aren't available right now. Top up your wallet to continue." };
577	      }
578	      return { checkout };
579	    }
580	
581	    // Wallet covers it — register immediately, exactly as this always has.
582	    let result: DomainRegistrationResult;
583	    try {
584	      result = await registerDomainCore(
585	        user,
586	        { domain, years: dTerm.years, contact, mailboxLocalPart, partnerSource: partnerSource ?? null },
587	        { priceCents, costCents, renewPriceCents, renewCostCents },
588	      );
589	    } catch (e) {
590	      if (e instanceof DomainOrderError) return { error: e.message };
591	      throw e;
592	    }
593	    if (result.kind !== "active") return { error: result.message };
594	    // `?new=1` triggers the one-time "domain registered" success banner +
595	    // hosting/VPS upsell on the domain page (app/dashboard/domains/[id]/page.tsx).
596	    redirect(`/dashboard/domains/${result.domainId}?new=1`);
597	  } finally {
598	    endSubmit(guardKey);
599	  }
600	}
