602	/**
603	 * Fulfil a domain registration paid by card — called only from
604	 * lib/fulfil-checkout.ts after the card leg is confirmed paid, exactly like
605	 * `placeHostingCardOrder`/`placeEmailCardOrder` (lib/actions-hosting.ts /
606	 * lib/actions-email-hosting.ts). Re-verifies EVERYTHING from the Stripe
607	 * session id alone — this file has `"use server"`, so this export is a
608	 * client-invokable Server Action, and it must trust nothing a caller supplies
609	 * except a session id that only Stripe itself could have produced as paid.
610	 *
611	 * The DomainOrderIntent row (not `purpose.sold`) is the authoritative source
612	 * for both the registrant contact and the frozen price — see that model's doc
613	 * comment in schema.prisma.
614	 */
615	export async function placeDomainCardOrder(
616	  sessionId: string,
617	): Promise<
618	  | { skip: true }
619	  | { error: string }
620	  | { domainId: string; kind: "active" }
621	  | { domainId: string; kind: "refunded" | "needs-review"; message: string }
622	> {
623	  const purpose = await getCheckoutPurpose(sessionId);
624	  if (purpose.kind !== "domainOrder") return { skip: true };
625	
626	  const [user, stashed] = await Promise.all([
627	    db.user.findUnique({ where: { id: purpose.userId } }),
628	    db.domainOrderIntent.findUnique({ where: { id: purpose.domainOrderId } }),
629	  ]);
630	  if (!user) return { error: "user not found for paid domain order" };
631	  if (!stashed) return { error: "domain order intent not found — it may already have been fulfilled and cleared" };
632	  // The row was written by THIS user's own purchaseDomain call, moments before
633	  // the session it is referenced from — a mismatch means the session's
634	  // metadata and the row it points at disagree about whose order this is,
635	  // which must never be trusted silently.
636	  if (stashed.userId !== purpose.userId) {
637	    return { error: `domain order intent ${stashed.id} belongs to a different user than the paid session` };
638	  }
639	
640	  const contact: RegistrantContact = {
641	    firstName: stashed.firstName,
642	    lastName: stashed.lastName,
643	    address1: stashed.address1,
644	    city: stashed.city,
645	    stateProvince: stashed.stateProvince,
646	    postalCode: stashed.postalCode,
647	    country: stashed.country,
648	    phone: stashed.phone,
649	    email: stashed.email,
650	  };
651	
652	  let result: DomainRegistrationResult;
653	  try {
654	    result = await registerDomainCore(
655	      user,
656	      {
657	        domain: stashed.domain,
658	        years: stashed.years,
659	        contact,
660	        mailboxLocalPart: stashed.mailboxLocalPart,
661	        partnerSource: stashed.partnerSource,
662	      },
663	      {
664	        priceCents: stashed.priceCents,
665	        costCents: stashed.costCents,
666	        // `(stashed as any)`: DomainOrderIntent.renewPriceCents/renewCostCents
667	        // aren't in the not-yet-regenerated Prisma Client (see schema.prisma's
668	        // doc comment on Domain.renewPriceCents) — reads as `undefined` until
669	        // `prisma db push` + `generate` run for real, which registerDomainCore
670	        // already treats the same as "no renewal price to freeze".
671	        renewPriceCents: (stashed as any).renewPriceCents ?? null,
672	        renewCostCents: (stashed as any).renewCostCents ?? null,
673	      },
674	    );
675	  } catch (e) {
676	    if (e instanceof DomainOrderError) return { error: e.message };
677	    throw e;
678	  }
679	
680	  if (result.kind === "active") return { domainId: result.domainId, kind: "active" };
681	  return { domainId: result.domainId, kind: result.kind, message: result.message };
682	}
