684	/** A renewal already landed if the registrar expiry runs ~a month past ours. */
685	const RENEW_SLACK_MS = 30 * 86400_000;
686	
687	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
688	  // Spend path: a manual renewal debits the wallet and spends at the registrar.
689	  // See purchaseDomain above.
690	  await assertNotImpersonating();
691	  const user = await requireUser();
692	  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
693	  // renewal runs in the worker and does not come through here, so no existing
694	  // domain can lapse because of this check.
695	  const unverifiedRenew = await emailVerificationError(user);
696	  if (unverifiedRenew) return { error: unverifiedRenew };
697	  const domain = await db.domain.findUnique({ where: { id: domainId } });
698	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
699	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
700	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
701	
702	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
703	  const guardKey = `renew:${domain.userId}:${domain.name}`;
704	  if (!beginSubmit(guardKey)) {
705	    return { error: "A renewal for this domain is already in progress." };
706	  }
707	
708	  try {
709	    const dTerm = domainTerm(domain.termYears);
710	    // Charge the FROZEN renewal price captured at registration/transfer time
711	    // (see Domain.renewPriceCents's doc comment in schema.prisma), not the
712	    // original first-year price — domains commonly renew higher, and what was
713	    // shown at checkout must be what gets charged. `(domain as any)` reads the
714	    // not-yet-live-DB column; falls back to priceCents for any row registered
715	    // before this field existed, or once it is null for another reason.
716	    const renewPerYearCents = (domain as any).renewPriceCents ?? domain.priceCents;
717	    const renewCents = domainTermPriceCents(renewPerYearCents, dTerm.years);
718	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
719	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
720	
721	    const dbExpiry = domain.expiresAt ?? null;
722	
723	    // Idempotency: charge and expiry advance together in one transaction below,
724	    // so if the registrar expiry is already ahead of ours a previous attempt
725	    // renewed but never got charged/recorded. Adopt that renewal instead of
726	    // buying a second year.
727	    let registrarExpiry: Date | undefined;
728	    try {
729	      registrarExpiry = (await domainInfo(domain.name)).expires;
730	    } catch {
731	      /* non-fatal: fall through to a normal renew */
732	    }
733	    const alreadyRenewed =
734	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
735	
736	    if (!alreadyRenewed) {
737	      // Same frozen-renewal-price reasoning as renewCents above, for the cost
738	      // side we tell the registrar to expect.
739	      const renewCostPerYear = (domain as any).renewCostCents ?? domain.costCents ?? domain.priceCents;
740	      try {
741	        await renewDomain(domain.name, dTerm.years, (renewCostPerYear || domain.priceCents) * dTerm.years);
742	      } catch (e: any) {
743	        // The registrar call is the FIRST thing that happens, before any debit,
744	        // so "you have not been charged" is a fact here, not a hope — and saying
745	        // it stops a customer retrying a renewal they think half-succeeded.
746	        return {
747	          error:
748	            `We couldn't renew ${domain.name} right now: ${errMsg(e)} ` +
749	            `Nothing has been charged. Wait a few minutes and try again; if it keeps failing, contact support.`,
750	        };
751	      }
752	      registrarExpiry = await domainInfo(domain.name)
753	        .then((i) => i.expires)
754	        .catch(() => undefined);
755	    }
756	
757	    const targetExpiry =
758	      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);
759	
760	    try {
761	      const charged = await db.$transaction(async (tx) => {
762	        // Re-read under the transaction: if a concurrent request already advanced
763	        // the expiry it also already took the money — do not charge again.
764	        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
765	        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
766	          return false;
767	        }
768	        await debitWallet(tx, domain.userId, renewCents);
769	        await tx.walletTransaction.create({
770	          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
771	        });
772	        await tx.domain.update({
773	          where: { id: domainId },
774	          // Reset the expiry-warning flag: this is a fresh term, so a future
775	          // approach to ITS expiry should warn again (see Domain.
776	          // expiryWarningSentAt's schema comment).
777	          data: { expiresAt: targetExpiry, status: "ACTIVE", expiryWarningSentAt: null },
778	        });
779	        return true;
780	      });
781	      if (!charged) {
782	        revalidatePath(`/dashboard/domains/${domainId}`);
783	        return {};
784	      }
785	    } catch (e) {
786	      if (e instanceof InsufficientBalanceError) {
787	        // The registrar renewal already succeeded — flag the uncollected charge
788	        // instead of silently swallowing it.
789	        await db.auditLog
790	          .create({
791	            data: {
792	              userId: domain.userId,
793	              action: "domain.renew.uncharged",
794	              detail: `${domain.name}: renewed at registrar but wallet debit of ${renewCents}c failed`,
795	            },
796	          })
797	          .catch(() => {});
798	        return { error: "Insufficient balance." };
799	      }
800	      throw e;
801	    }
802	    sendDomainRenewedEmail(domain.userId, domain.name, targetExpiry);
803	    revalidatePath(`/dashboard/domains/${domainId}`);
804	    return {};
805	  } finally {
806	    endSubmit(guardKey);
807	  }
808	}
