831	  const domainId = String(formData.get("domainId") ?? "");
832	  let ctx;
833	  try {
834	    ctx = await ownedDomain(domainId);
835	  } catch (e: any) {
836	    return { error: e.message };
837	  }
838	  const parsed = z
839	    .object({
840	      name: z.string().max(120).default(""),
841	      type: z.enum(RECORD_TYPES),
842	      address: z.string().min(1).max(500),
843	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
844	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
845	    })
846	    .safeParse({
847	      name: formData.get("name") ?? "",
848	      type: formData.get("type"),
849	      address: formData.get("address"),
850	      ttl: formData.get("ttl") || 300,
851	      mxPref: formData.get("mxPref") || undefined,
852	    });
853	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
854	
855	  // "@" or blank => apex (name.com uses empty host for apex)
856	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
857	  try {
858	    await addRecord(ctx.domain.name, {
859	      host,
860	      type: parsed.data.type,
861	      answer: parsed.data.address,
862	      ttl: parsed.data.ttl,
863	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
864	    });
