866	    // Say what went wrong AND what to do about it. A bare error string
867	    // ("422 Unprocessable Entity") tells a customer nothing they can act on;
868	    // this product's standard is that an error explains both halves.
869	    return {
870	      error:
871	        `This record couldn't be added: ${errMsg(e)} ` +
872	        `Check the value matches the record type (an A record needs an IPv4 address, a CNAME needs a hostname), ` +
873	        `then try again. Nothing was changed.`,
874	    };
875	  }
876	  revalidatePath(`/dashboard/domains/${domainId}`);
877	  return {};
