907	/**
908	 * One-click: point apex + www at the platform's public IP.
909	 *
910	 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
911	 * only then add the replacements — so a registrar hiccup, a rate limit or a
912	 * network blip in between took the domain DARK and left it that way, with an
913	 * error message that did not say the old records were already gone. That is the
914	 * "six domains dark while the run scored 4/4" failure shape: destructive work
915	 * done first, on the assumption the constructive half cannot fail.
916	 *
917	 * The new order is also idempotent — an A record already pointing at `ip` is
918	 * kept rather than churned — so clicking twice is free, and a half-finished run
919	 * can simply be retried.
920	 */
921	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
922	  let ctx;
923	  try {
924	    ctx = await ownedDomain(domainId);
925	  } catch (e: any) {
926	    return { error: e.message };
927	  }
928	  const ip = process.env.PUBLIC_IP;
929	  if (!ip) {
930	    return {
931	      error:
932	        "This platform doesn't have a public IP configured, so there is nothing to point the domain at. " +
933	        "Contact support — this is a platform configuration problem, not something you can fix from here.",
934	    };
935	  }
936	
937	  const done: string[] = [];
938	  try {
939	    const recs = await listRecords(ctx.domain.name);
940	    for (const host of ["", "www"]) {
941	      const label = host === "" ? ctx.domain.name : `www.${ctx.domain.name}`;
942	      const existing = recs.filter((r) => r.host === host && r.type === "A");
943	      const keep = existing.find((r) => r.answer === ip);
944	      // Constructive half FIRST: the name resolves somewhere at every instant.
945	      if (!keep) await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
946	      // Only now retire the records that point elsewhere.
947	      for (const r of existing) {
948	        if (keep && r.id === keep.id) continue;
949	        await deleteRecord(ctx.domain.name, r.id);
950	      }
951	      done.push(label);
952	    }
953	  } catch (e: any) {
954	    const reason = errMsg(e);
955	    return {
956	      error:
957	        `Part of this change was rejected (${reason}). ` +
958	        (done.length > 0
959	          ? `${done.join(" and ")} ${done.length === 1 ? "was" : "were"} pointed at ${ip} and ${done.length === 1 ? "is" : "are"} live; the rest was not changed. `
960	          : "Nothing was changed and your existing records are untouched. ") +
961	        `Wait a minute and click Point at server again — it is safe to repeat.`,
962	    };
963	  }
964	  revalidatePath(`/dashboard/domains/${domainId}`);
965	  return {};
966	}
