51	/* A record shape the client can build for presets / imports. Host "" = apex. */
52	export type RecordInput = {
53	  host: string;
54	  type: string;
55	  answer: string;
56	  ttl?: number;
57	  priority?: number;
58	};
59	
60	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
61	
62	function normHost(h: string): string {
63	  const t = (h ?? "").trim();
64	  return ["@", ""].includes(t) ? "" : t.replace(/\.$/, "");
65	}
66	
67	/** True if `want` is already present in `existing` (host+type+answer, MX also priority). */
68	function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
69	  const wh = normHost(want.host);
70	  const wa = want.answer.trim().toLowerCase();
71	  return existing.some((r) => {
72	    if (r.host !== wh) return false;
73	    if (r.type !== want.type) return false;
74	    if (r.answer.trim().toLowerCase() !== wa) return false;
75	    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
76	    return true;
77	  });
78	}
79	
80	const recordInputSchema = z.object({
81	  host: z.string().max(120).default(""),
82	  type: z.enum(RECORD_TYPES),
83	  answer: z.string().min(1).max(2000),
84	  ttl: z.coerce.number().int().min(60).max(86400).default(300),
85	  priority: z.coerce.number().int().min(0).max(65535).optional(),
86	});
87	
88	export type BulkResult = {
89	  error?: string;
90	  added?: string[];
91	  skipped?: string[];
92	  failed?: { record: string; reason: string }[];
93	  note?: string;
94	};
95	
96	function label(r: RecordInput): string {
97	  const h = normHost(r.host) || "@";
98	  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
99	  return `${r.type} ${h} → ${pri}${r.answer}`;
100	}
101	
102	/**
103	 * Add many DNS records at once, skipping any that already exist. Powers the
104	 * quick-setup presets and DNS import. Ownership-checked; domain must be ACTIVE.
105	 */
106	export async function addDnsRecordsBulk(
107	  domainId: string,
108	  records: RecordInput[]
109	): Promise<BulkResult> {
110	  let ctx;
111	  try {
112	    ctx = await ownedActiveDomain(domainId);
113	  } catch (e) {
114	    return { error: errMsg(e) };
115	  }
116	  if (!Array.isArray(records) || records.length === 0) return { error: "No records to add." };
117	  if (records.length > 100) return { error: "Too many records in one request (max 100)." };
118	
119	  const clean: RecordInput[] = [];
120	  for (const raw of records) {
121	    const parsed = recordInputSchema.safeParse(raw);
122	    if (!parsed.success) {
123	      return { error: `Invalid record: ${parsed.error.issues[0]?.message ?? "bad record"}` };
124	    }
125	    clean.push({ ...parsed.data, host: normHost(parsed.data.host) });
126	  }
127	
128	  let existing: DnsRecord[];
129	  try {
130	    existing = await listRecords(ctx.domain.name);
131	  } catch (e) {
132	    return { error: `Could not read current records: ${errMsg(e)}` };
133	  }
134	
135	  const added: string[] = [];
136	  const skipped: string[] = [];
137	  const failed: { record: string; reason: string }[] = [];
138	
139	  for (const rec of clean) {
140	    if (recordExists(existing, rec)) {
141	      skipped.push(label(rec));
142	      continue;
143	    }
144	    try {
145	      await addRecord(ctx.domain.name, {
146	        host: rec.host,
147	        type: rec.type,
148	        answer: rec.answer,
149	        ttl: rec.ttl ?? 300,
150	        priority: rec.type === "MX" || rec.type === "SRV" ? rec.priority ?? 10 : undefined,
151	      });
152	      added.push(label(rec));
153	      // Track locally so later records in the same batch dedupe correctly.
154	      existing.push({ id: -1, host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 300, priority: rec.priority });
155	    } catch (e) {
156	      failed.push({ record: label(rec), reason: errMsg(e) });
157	    }
158	  }
159	
160	  await db.auditLog.create({
161	    data: {
162	      userId: ctx.user.id,
163	      action: "domain.dns_bulk_add",
164	      detail: `${ctx.domain.name}: +${added.length} skip ${skipped.length} fail ${failed.length}`,
165	    },
166	  });
167	  revalidatePath(`/dashboard/domains/${domainId}`);
168	  return { added, skipped, failed: failed.length ? failed : undefined };
169	}
