277	/* ------------------------------------------------------------------ *
278	 * URL forwarding / redirects (name.com URL-forwarding API).
279	 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
280	 * Degrades to a persisted-intent Setting + note when unconfigured.
281	 * ------------------------------------------------------------------ */
282	
283	export type Redirect = { host: string; forwardsTo: string; type: string };
284	
285	const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;
286	
287	async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
288	  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
289	  if (!s?.value) return [];
290	  try {
291	    const parsed = JSON.parse(s.value);
292	    return Array.isArray(parsed) ? parsed : [];
293	  } catch {
294	    return [];
295	  }
296	}
297	
298	async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
299	  await db.setting.upsert({
300	    where: { key: redirectStoreKey(domainId) },
301	    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
302	    update: { value: JSON.stringify(list) },
303	  });
304	}
305	
306	export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };
307	
308	/** List forwardings — live from name.com when possible, else persisted intent. */
309	export async function listRedirects(domainId: string): Promise<RedirectsView> {
310	  let ctx;
311	  try {
312	    ctx = await ownedDomain(domainId);
313	  } catch (e) {
314	    return { forwards: [], live: false, error: errMsg(e) };
315	  }
316	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
317	    try {
318	      const forwards = await listUrlForwarding(ctx.domain.name);
319	      return { forwards, live: true };
320	    } catch (e) {
321	      // Fall back to intent store but tell the truth about why.
322	      const forwards = await readRedirectIntent(domainId);
323	      return { forwards, live: false, note: `Live forwarding unavailable (${errMsg(e)}); showing saved intent.` };
324	    }
325	  }
326	  const forwards = await readRedirectIntent(domainId);
327	  return { forwards, live: false, note: "Registrar not connected — showing saved intent that will apply once live." };
328	}
329	
330	const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;
331	
332	export async function setRedirect(
333	  domainId: string,
334	  hostRaw: string,
335	  forwardsTo: string,
336	  type: string
337	): Promise<RedirectsView> {
338	  let ctx;
339	  try {
340	    ctx = await ownedDomain(domainId);
341	  } catch (e) {
342	    return { forwards: [], live: false, error: errMsg(e) };
343	  }
344	  const host = normHost(hostRaw);
345	  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
346	  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
347	  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };
348	
349	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
350	  if (canLive) {
351	    try {
352	      // Upsert: delete any existing forwarding for this host, then create.
353	      try {
354	        await deleteUrlForwarding(ctx.domain.name, host);
355	      } catch {
356	        /* none existed */
357	      }
358	      await addUrlForwarding(ctx.domain.name, { host, forwardsTo: url.data, type: t });
359	    } catch (e) {
360	      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
361	    }
362	  } else {
363	    const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
364	    list.push({ host, forwardsTo: url.data, type: t });
365	    await writeRedirectIntent(domainId, list);
366	  }
367	
368	  await db.auditLog.create({
369	    data: { userId: ctx.user.id, action: "domain.redirect_set", detail: `${ctx.domain.name} ${host || "@"} -> ${url.data} (${t})${canLive ? " live" : " intent"}` },
370	  });
371	  revalidatePath(`/dashboard/domains/${domainId}`);
372	  const view = await listRedirects(domainId);
373	  return {
374	    ...view,
375	    note: canLive
376	      ? "Redirect saved via URL forwarding. It can take a little while to take effect."
377	      : "Saved. This redirect will be applied via URL forwarding once the domain is active.",
378	  };
379	}
380	
381	export async function deleteRedirect(domainId: string, hostRaw: string): Promise<RedirectsView> {
382	  let ctx;
383	  try {
384	    ctx = await ownedDomain(domainId);
385	  } catch (e) {
386	    return { forwards: [], live: false, error: errMsg(e) };
387	  }
388	  const host = normHost(hostRaw);
389	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
390	  if (canLive) {
391	    try {
392	      await deleteUrlForwarding(ctx.domain.name, host);
393	    } catch (e) {
394	      return { ...(await listRedirects(domainId)), error: `Could not remove redirect: ${errMsg(e)}` };
395	    }
396	  }
397	  const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
398	  await writeRedirectIntent(domainId, list);
399	  await db.auditLog.create({
400	    data: { userId: ctx.user.id, action: "domain.redirect_delete", detail: `${ctx.domain.name} ${host || "@"}` },
401	  });
402	  revalidatePath(`/dashboard/domains/${domainId}`);
403	  return { ...(await listRedirects(domainId)), note: "Redirect removed." };
404	}
