433	export async function setRegistrarLock(domainId: string, locked: boolean): Promise<LockView> {
434	  let ctx;
435	  try {
436	    ctx = await ownedDomain(domainId);
437	  } catch (e) {
438	    return { locked: false, live: false, error: errMsg(e) };
439	  }
440	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
441	  let live = false;
442	  let note: string | undefined;
443	  if (canLive) {
444	    try {
445	      if (locked) {
446	        await lockDomain(ctx.domain.name);
447	      } else {
448	        await unlockDomain(ctx.domain.name);
449	      }
450	      live = true;
451	      note = locked
452	        ? "Registrar lock enabled — the domain is protected against unauthorized transfers."
453	        : "Registrar lock disabled — the domain can now be transferred to another registrar.";
454	    } catch (e) {
