456	    }
457	  } else {
458	    note = "Saved. This lock preference will be applied once the domain is active.";
459	  }
460	  await db.setting.upsert({
461	    where: { key: lockStoreKey(domainId) },
462	    create: { key: lockStoreKey(domainId), value: String(locked) },
463	    update: { value: String(locked) },
464	  });
465	  await db.auditLog.create({
466	    data: { userId: ctx.user.id, action: "domain.registrar_lock", detail: `${ctx.domain.name} -> ${locked ? "locked" : "unlocked"}${live ? " (live)" : ""}` },
467	  });
468	  revalidatePath(`/dashboard/domains/${domainId}`);
469	  return { locked, live, note };
470	}
