12	const HOST_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/;
13	
14	async function ownedDomain(domainId: string) {
15	  const user = await requireUser();
16	  const domain = await db.domain.findUnique({ where: { id: domainId } });
17	  if (!domain) throw new Error("Not found");
18	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
19	  return { user, domain };
20	}
