33	/**
34	 * Persist custom nameservers on the Domain and, when the domain is ACTIVE
35	 * and the registrar is configured, push them to name.com. Two or more
36	 * valid hostnames are required for a registrar update; an empty list clears
37	 * the override locally (name.com default NS remain untouched).
38	 */
39	export async function updateNameservers(
40	  domainId: string,
41	  nameservers: string[]
42	): Promise<NameserverResult> {
43	  const { user, domain } = await ownedDomain(domainId);
44	
45	  const cleaned = (nameservers ?? [])
46	    .map((n) => n.trim().toLowerCase().replace(/\.$/, ""))
47	    .filter(Boolean);
48	  const unique = [...new Set(cleaned)];
49	
50	  for (const ns of unique) {
51	    if (!HOST_RE.test(ns)) return { error: `Invalid nameserver hostname: ${ns}` };
52	  }
53	  if (unique.length > 13) return { error: "At most 13 nameservers are allowed." };
54	  if (unique.length === 1) return { error: "Provide at least two nameservers." };
55	
56	  let registrarHit = false;
57	  let note: string | undefined;
58	
59	  if (unique.length >= 2) {
60	    if (domain.status === "ACTIVE" && registrarConfigured()) {
61	      try {
62	        await setNameservers(domain.name, unique);
63	        registrarHit = true;
64	      } catch (e) {
65	        return { error: `Registrar rejected the update: ${errMsg(e)}` };
66	      }
67	    } else {
68	      note =
69	        "Saved. These will be applied at the registrar once the domain is active and the registrar is configured.";
70	    }
71	  }
72	
73	  await db.domain.update({ where: { id: domainId }, data: { nameservers: unique } });
74	  await db.auditLog.create({
75	    data: {
76	      userId: user.id,
77	      action: "domain.nameservers",
78	      detail: `${domainId} -> [${unique.join(", ")}]${registrarHit ? " (registrar)" : ""}`,
79	    },
80	  });
81	  revalidatePath(`/dashboard/domains/${domainId}`);
82	  return { nameservers: unique, registrarHit, note };
83	}
