127	/**
128	 * Prepare the domain for an outbound transfer: unlock the registrar lock and
129	 * retrieve the EPP/auth code from name.com, persisting it to `transferEpp`.
130	 * If the registrar isn't configured we can only surface a previously stored
131	 * code (or ask the customer to contact support). Ownership-checked.
132	 */
133	export async function requestTransferOut(domainId: string): Promise<TransferResult> {
134	  const { user, domain } = await ownedDomain(domainId);
135	
136	  if (domain.status !== "ACTIVE") {
137	    return { error: "The domain must be active before it can be transferred out." };
138	  }
