30	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
31	
32	/** Statuses a customer may retry a transfer over (nothing live is clobbered). */
33	const RETRYABLE = ["FAILED", "TRANSFER_FAILED"] as const;
34	
35	function errMsg(e: unknown): string {
36	  return registrarSafeMessage(e);
37	}
38	
39	/** Never let a registrar error echo the customer's auth code back into the UI/logs. */
40	function scrubbed(msg: string, authCode: string): string {
41	  return authCode ? msg.split(authCode).join("***") : msg;
42	}
43	
44	class DuplicateDomainError extends Error {
45	  constructor() {
46	    super("DUPLICATE_DOMAIN");
47	    this.name = "DuplicateDomainError";
48	  }
49	}
