53	/* ------------------------------------------------------------------ *
54	 * Step 1 — quote
55	 * ------------------------------------------------------------------ */
56	
57	export type TransferQuote = {
58	  domain: string;
59	  transferable: boolean;
60	  reason: string | null;
61	  /** RETAIL total the customer pays — the transfer plus a 1-year extension. */
62	  priceCents: number | null;
63	};
64	
65	/**
66	 * Is this domain transferable, and what does it cost? Read-only; safe to call
67	 * repeatedly from the wizard. Rate-limited because every call fans out to the
68	 * registrar.
69	 */
70	export async function quoteTransferIn(raw: string): Promise<{ error?: string; quote?: TransferQuote }> {
71	  const user = await requireUser();
72	  if (!(await getSettingBool("feature_domains", true))) {
73	    return { error: "Domain transfers are currently unavailable." };
74	  }
75	  if (!transfersAvailable()) {
76	    return { error: "Domain transfers aren't configured yet (registrar API keys missing)." };
77	  }
78	  const rl = checkRateLimit(`domain-transfer-quote:${user.id}`, { max: 20, windowMs: 60_000 });
79	  if (!rl.ok) return { error: `Too many lookups — try again in ${rl.retryAfterSec}s.` };
80	
81	  const domain = raw.toLowerCase().trim().replace(/^https?:\/\//, "").replace(/\/.*$/, "");
82	  if (!DOMAIN_RE.test(domain)) return { error: "Enter a domain like example.com (no www, no path)." };
83	
84	  const existing = await db.domain.findUnique({ where: { name: domain } });
85	  if (existing) {
86	    if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
87	    if (existing.status === "TRANSFER_PENDING") {
88	      return { error: "A transfer for this domain is already in progress on your account." };
89	    }
90	    if (!RETRYABLE.includes(existing.status as (typeof RETRYABLE)[number])) {
91	      return { error: `${domain} is already on your account (status: ${existing.status.toLowerCase()}).` };
92	    }
93	  }
94	
95	  let check: TransferCheck;
96	  try {
97	    check = await checkTransfer(domain);
98	  } catch (e) {
99	    return { error: errMsg(e) };
100	  }
101	  return {
102	    quote: {
103	      domain,
104	      transferable: check.transferable && check.priceCents !== null,
105	      reason: check.reason,
106	      priceCents: check.priceCents === null ? null : transferChargeCents(check.priceCents),
107	    },
108	  };
109	}
