111	/* ------------------------------------------------------------------ *
112	 * Steps 2-4 — pre-flight, auth code, submit
113	 * ------------------------------------------------------------------ */
114	
115	/**
116	 * Submit an inbound transfer.
117	 *
118	 * ORDER MATTERS — the registrar is called BEFORE any money moves:
119	 *   1. re-quote server-side (the price the client showed is never trusted),
120	 *   2. `createTransfer` at the registrar,
121	 *   3. debit + invoice + Domain row, all in ONE transaction.
122	 *
123	 * So a charge for a transfer that was never submitted is structurally
124	 * impossible. A double charge is impossible three ways over: the in-process
125	 * guard blocks the double-click, `Domain.name` is UNIQUE inside the charging
126	 * transaction (and the retry path CAS-swaps off the exact status we read), and
127	 * name.com itself refuses a second transfer for a domain already in flight.
128	 *
129	 * If the debit fails after a successful submit (balance drained in the seconds
130	 * between the check and the charge) we cancel the transfer back out at the
131	 * registrar rather than quietly performing work nobody paid for.
132	 */
133	export async function submitTransferIn(prev: any, formData: FormData): Promise<{ error?: string }> {
134	  const user = await requireUser();
135	  // Spend path: never move a customer's money while an admin is impersonating.
136	  await assertNotImpersonating();
137	  // Purchase gate: an unverified address means we cannot reach the person we
138	  // are about to charge. See lib/email-verification.ts.
139	  const unverified = await emailVerificationError(user);
140	  if (unverified) return { error: unverified };
141	
142	  if (!(await getSettingBool("feature_domains", true))) {
143	    return { error: "Domain transfers are currently unavailable." };
144	  }
145	  if (!transfersAvailable()) {
146	    return { error: "Domain transfers aren't configured yet (registrar API keys missing)." };
147	  }
148	  const rl = checkRateLimit(`domain-transfer-in:${user.id}`, { max: 5, windowMs: 10 * 60_000 });
149	  if (!rl.ok) {
150	    return { error: `Too many transfer attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)} min.` };
151	  }
152	
153	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
154	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
155	
156	  const authCode = String(formData.get("authCode") ?? "").trim();
157	  if (authCode.length < 4 || authCode.length > 255) {
158	    return { error: "Enter the EPP / auth code from your current registrar (4–255 characters)." };
159	  }
160	
161	  // The pre-flight checklist is a real gate, not decoration: the registry will
162	  // reject a transfer that fails any of these, and the customer eats a 5-7 day
163	  // round trip for nothing. Confirm every box came back ticked.
164	  const acks = ["ackUnlocked", "ackPrivacy", "ackAge", "ackApproval"];
165	  if (acks.some((k) => formData.get(k) !== "1")) {
166	    return { error: "Confirm every pre-flight item before we submit the transfer." };
167	  }
168	
169	  const expectedCents = Math.round(Number(formData.get("expectedCents") ?? 0));
170	
171	  const guardKey = `transfer-in:${user.id}:${domain}`;
172	  if (!beginTransferSubmit(guardKey)) {
173	    return { error: "That transfer is already being submitted — give it a moment before retrying." };
174	  }
175	
176	  try {
177	    const existing = await db.domain.findUnique({ where: { name: domain } });
178	    if (existing) {
179	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
180	      if (existing.status === "TRANSFER_PENDING") {
181	        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
182	      }
183	      if (!RETRYABLE.includes(existing.status as (typeof RETRYABLE)[number])) {
184	        return { error: `${domain} is already on your account (status: ${existing.status.toLowerCase()}).` };
185	      }
186	    }
187	
188	    // Re-quote server-side. The wizard's number is a display; this is the price.
189	    let check: TransferCheck;
190	    try {
191	      check = await checkTransfer(domain);
192	    } catch (e) {
193	      return { error: errMsg(e) };
194	    }
195	    if (!check.transferable || check.priceCents === null || check.costCents === null) {
196	      return { error: check.reason ?? "This domain can't be transferred in right now." };
197	    }
198	    const totalCents = transferChargeCents(check.priceCents); // retail — what we charge
199	    const registrarCostCents = check.costCents; // cost — what we tell name.com to spend
200	
201	    if (expectedCents !== totalCents) {
202	      return {
203	        error:
204	          `The registrar's price changed while you were filling this in — it's now $${(totalCents / 100).toFixed(2)}. ` +
205	          `Go back a step to re-check and confirm the new price. Nothing has been charged.`,
206	      };
207	    }
208	    if (user.balanceCents < totalCents) {
209	      return { error: `Insufficient balance — this transfer costs $${(totalCents / 100).toFixed(2)}.` };
210	    }
211	
212	    // ---- Registrar first. No money has moved at this point. ----
213	    let submitted;
214	    try {
215	      submitted = await createTransfer(domain, authCode, registrarCostCents);
216	    } catch (e) {
217	      return { error: `The registrar refused the transfer: ${scrubbed(errMsg(e), authCode)} (you were not charged).` };
218	    }
219	
220	    // Recorded BEFORE the charge so that even a hard crash here leaves ops a
221	    // trace of a transfer that is live at the registrar but not yet billed.
222	    await db.auditLog
223	      .create({
224	        data: {
225	          userId: user.id,
226	          action: "domain.transfer_in.submitted",
227	          detail: `${domain} status=${submitted.status} charge=${totalCents}c`,
228	        },
229	      })
230	      .catch(() => {});
231	
232	    // ---- Charge + row, atomically. ----
233	    let domainId: string;
234	    try {
235	      domainId = await db.$transaction(async (tx) => {
236	        const transferData = {
237	          status: "TRANSFER_PENDING" as const,
238	          isTransferIn: true,
239	          transferAuthCodeEnc: encryptSecret(authCode),
240	          transferStartedAt: new Date(),
241	          transferStatus: submitted.status,
242	          transferEmail: submitted.email,
243	          priceCents: check.priceCents!,
244	          costCents: check.costCents!,
245	          // A transfer is already priced at the TLD's RENEWAL rate (it includes
246	          // a 1-year extension, not a first-year promo rate) — so next year's
247	          // renewal should charge this SAME rate again, not re-derive it later.
248	          // See Domain.renewPriceCents's doc comment in schema.prisma for why
249	          // this pair is not yet in the live DB/generated Prisma Client.
250	          renewPriceCents: check.priceCents!,
251	          renewCostCents: check.costCents!,
252	          termYears: TRANSFER_TERM_YEARS,
253	          registrar: "name.com",
254	          error: null,
255	        } as any;
256	        // Write the row FIRST: a unique conflict or a lost CAS aborts the whole
257	        // transaction before the wallet is touched.
258	        let id: string;
259	        if (existing) {
260	          const swapped = await tx.domain.updateMany({
261	            where: { id: existing.id, status: existing.status },
262	            data: transferData,
263	          });
264	          if (swapped.count === 0) throw new DuplicateDomainError();
265	          id = existing.id;
266	        } else {
267	          const created = await tx.domain.create({
268	            data: { name: domain, userId: user.id, ...transferData },
269	          });
270	          id = created.id;
271	        }
272	        await debitWallet(tx, user.id, totalCents);
273	        await tx.walletTransaction.create({
274	          data: {
275	            userId: user.id,
276	            amountCents: -totalCents,
277	            description: transferChargeDescription(domain),
278	          },
279	        });
280	        await tx.invoice.create({
281	          data: invoiceCreateData({
282	            userId: user.id,
283	            description: transferChargeDescription(domain),
284	            status: "PAID",
285	            lineItems: [
286	              {
287	                description: `Domain transfer in — ${domain} (adds 1 year to the registration)`,
288	                qty: 1,
289	                unitCents: totalCents,
290	                amountCents: totalCents,
291	              },
292	            ],
293	          }),
294	        });
295	        return id;
296	      });
297	    } catch (e) {
298	      // The transfer IS live at the registrar but we could not bill it. Undo the
299	      // submission rather than do unpaid work; if the registrar won't cancel,
300	      // flag it for ops instead of silently swallowing it.
301	      let cancelled = false;
302	      try {
303	        await cancelTransfer(domain);
304	        cancelled = true;
305	      } catch {
306	        /* registrar refused the cancel — ops has to unwind it manually */
307	      }
308	      await db.auditLog
309	        .create({
310	          data: {
311	            userId: user.id,
312	            action: "domain.transfer_in.uncharged",
313	            detail: `${domain}: submitted but not charged (${errMsg(e)}) — cancelled=${cancelled}`.slice(0, 500),
314	          },
315	        })
316	        .catch(() => {});
317	
318	      if (e instanceof InsufficientBalanceError) {
319	        return {
320	          error: cancelled
321	            ? "Your balance dropped below the transfer price before we could charge it, so we cancelled the transfer at the registrar. Top up and try again — you were not charged."
322	            : "Your balance dropped below the transfer price before we could charge it. We've flagged this for our team — you were not charged. Please contact support before retrying.",
323	        };
324	      }
325	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
326	        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
327	      }
328	      throw e;
329	    }
330	
331	    await db.notification
332	      .create({
333	        data: {
334	          userId: user.id,
335	          title: `Transfer started: ${domain}`,
336	          body:
337	            `We've submitted the transfer to the registrar. Inbound transfers normally take 5–7 days ` +
338	            `and you must approve a confirmation email from your CURRENT registrar before it can complete.`,
339	          href: `/dashboard/domains/${domainId}`,
340	        },
341	      })
342	      .catch(() => {});
343	
344	    revalidatePath("/dashboard/domains");
345	    redirect(`/dashboard/domains/${domainId}`);
346	  } finally {
347	    endTransferSubmit(guardKey);
348	  }
349	}
350	
351	/* ------------------------------------------------------------------ *
352	 * Cancel an in-flight transfer
353	 * ------------------------------------------------------------------ */
354	
355	/**
356	 * Cancel an inbound transfer at the registrar and credit the customer back.
357	 *
358	 * The credit happens ONLY after the registrar confirms the cancellation — we do
359	 * not assume a refund we haven't been given. If the registrar refuses (the most
360	 * common reason being that the transfer already completed at the registry) we
361	 * say so and move no money.
362	 */
363	export async function cancelTransferIn(
364	  domainId: string
365	): Promise<{ error?: string; note?: string }> {
366	  const user = await requireUser();
367	  // Credits the wallet — same guard as every other money-moving action.
368	  await assertNotImpersonating();
369	
370	  const domain = await db.domain.findUnique({ where: { id: domainId } });
371	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
372	  if (!domain.isTransferIn || domain.status !== "TRANSFER_PENDING") {
373	    return { error: "There's no transfer in progress for this domain." };
374	  }
375	
376	  const rl = checkRateLimit(`domain-transfer-cancel:${user.id}`, { max: 6, windowMs: 10 * 60_000 });
377	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
378	
379	  const guardKey = `transfer-cancel:${domain.userId}:${domain.name}`;
380	  if (!beginTransferSubmit(guardKey)) return { error: "That cancellation is already being processed." };
381	
382	  try {
383	    try {
384	      await cancelTransfer(domain.name);
385	    } catch (e) {
386	      return {
387	        error:
388	          `The registrar wouldn't cancel this transfer: ${errMsg(e)}. ` +
389	          `That usually means it has already gone through at the registry — refresh in a few minutes. ` +
390	          `Nothing has been credited or charged.`,
391	      };
392	    }
393	
394	    const refundCents = transferChargeCents(domain.priceCents);
395	    const settled = await settleFailedTransferIn({
396	      domainId: domain.id,
397	      transferStatus: "cancelled",
398	      reason: "Transfer cancelled at your request.",
399	    });
400	    await db.auditLog
401	      .create({ data: { userId: user.id, action: "domain.transfer_in.cancelled", detail: domain.name } })
402	      .catch(() => {});
403	    revalidatePath(`/dashboard/domains/${domainId}`);
404	    revalidatePath("/dashboard/domains");
405	
406	    return {
407	      note: settled
408	        ? `Transfer cancelled at the registrar and $${(refundCents / 100).toFixed(2)} credited back to your wallet.`
409	        : "This transfer had already been settled — no further credit was applied.",
410	    };
411	  } finally {
412	    endTransferSubmit(guardKey);
413	  }
414	}
