9	export function registrarConfigured(): boolean {
10	  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
11	}
12	
13	/**
14	 * Thrown at the registrar HTTP boundary (`nc()` below) instead of a plain
15	 * `Error`, so every catch site up the call chain can show a customer a safe,
16	 * registrar-name-free message while still keeping the real failure for ops.
17	 *
18	 * `message` (inherited) stays the RAW text for anything that logs `e.message`
19	 * without checking `instanceof` — `rawMessage` is the same value under an
20	 * explicit name for call sites that DO check. `customerMessage` is the only
21	 * one of the three ever allowed in front of a customer.
22	 *
23	 * The real production incident this exists for: a registrar 402 ("Payment
24	 * failed") was shown to a customer verbatim, registrar name included, because
25	 * every catch site just did `{ error: String(e.message) }`.
26	 */
27	export class RegistrarError extends Error {
28	  readonly registrarId: string;
29	  readonly rawMessage: string;
30	  readonly customerMessage: string;
31	
32	  constructor(registrarId: string, rawMessage: string) {
33	    super(rawMessage);
34	    this.name = "RegistrarError";
35	    this.registrarId = registrarId;
36	    this.rawMessage = rawMessage;
37	    this.customerMessage = classifyRegistrarFailure(rawMessage);
38	  }
39	}
40	
41	const PAYMENT_FAILURE_RE = /payment|balance|insufficient|declin|charge/i;
42	
43	/** Generic fallback — hedges "no charge" rather than asserting it, since not every call site is a payment. */
44	const GENERIC_CUSTOMER_MESSAGE =
45	  "Something went wrong on our end completing this request. No charge was made if this was a payment action; please try again or contact support.";
46	
47	const PAYMENT_CUSTOMER_MESSAGE =
48	  "We couldn't complete this right now — no charge was made. Please try again or contact support.";
49	
50	/** Pattern-match a raw registrar error into a customer-safe category. Never echoes `raw`. */
51	function classifyRegistrarFailure(raw: string): string {
52	  return PAYMENT_FAILURE_RE.test(raw) ? PAYMENT_CUSTOMER_MESSAGE : GENERIC_CUSTOMER_MESSAGE;
53	}
54	
55	/**
56	 * Registrar-safe message for any caught error: `customerMessage` when it's a
57	 * `RegistrarError`, otherwise the same raw-message-sliced behavior every catch
58	 * site already used. Centralizing this means every call site that reads a
59	 * caught registrar failure gets the fix by importing this instead of
60	 * hand-rolling `String(e?.message ?? e)`.
61	 *
62	 * Also logs `rawMessage` + `registrarId` server-side (console.error, same
63	 * mechanism this module already uses elsewhere) so a real failure is still
64	 * diagnosable from the logs even though the customer never sees it — most of
65	 * the ~15 call sites this replaces had no per-error logging of their own to
66	 * hook into, so this is the one place that can guarantee it happens.
67	 */
68	export function registrarSafeMessage(e: unknown): string {
69	  if (e instanceof RegistrarError) {
70	    console.error(`[registrar:${e.registrarId}] ${e.rawMessage}`);
71	    return e.customerMessage;
72	  }
73	  return String(e instanceof Error ? e.message : e).slice(0, 200);
74	}
