77	 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
78	 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
79	 * exercised end to end without touching the registrar or a real domain.
80	 */
81	export function transfersAvailable(): boolean {
82	  return SANDBOX || registrarConfigured();
83	}
