94	async function nc(
95	  method: string,
96	  path: string,
97	  body?: unknown,
98	  opts?: { nullOn404?: boolean }
99	): Promise<any> {
100	  if (!registrarConfigured()) throw new RegistrarError("namecom", "registrar is not configured");
101	  const res = await fetch(`${baseUrl()}${path}`, {
102	    method,
103	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
104	    body: body ? JSON.stringify(body) : undefined,
105	    signal: AbortSignal.timeout(30_000),
106	  });
107	  const text = await res.text();
108	  let json: any = {};
109	  try {
110	    json = text ? JSON.parse(text) : {};
111	  } catch {
112	    /* non-JSON error body */
113	  }
114	  if (!res.ok) {
115	    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
116	    // that has already dropped off the registrar's list) — let them opt in to a
117	    // null instead of an exception rather than string-matching an error message.
118	    if (opts?.nullOn404 && res.status === 404) return null;
119	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
120	    throw new RegistrarError("namecom", msg);
121	  }
122	  return json;
123	}
