127	/** Fallback markup when no admin setting is saved. Matches the old hardcoded value. */
128	const DEFAULT_MARKUP_PCT = 25;
129	
130	/**
131	 * Platform markup over the registrar's cost, as a percentage.
132	 *
133	 * MONEY BUG (fixed 2026-07-26): Settings → Domains writes `domain_markup_percent`
134	 * and displays it, but NOTHING read it — the only references were the stored
135	 * default, the save whitelist, and the admin input itself. Meanwhile this function
136	 * read `DOMAIN_MARKUP_PCT`, which is not set in `.env`, so every domain price
137	 * silently carried the hardcoded 25%. The panel therefore showed an operator **0%**
138	 * while customers were charged **25%**, and editing the field changed nothing.
139	 *
140	 * The admin setting is now the source of truth, with the env var as the fallback so
141	 * an operator who had set it keeps their behaviour. The stored default is corrected
142	 * from "0" to 25 so the panel states what is genuinely applied — displaying 0% while
143	 * charging 25% is precisely the class of untruth this codebase keeps producing.
144	 *
145	 * Safe to change now: zero domains have been sold and the setting had never been
146	 * saved, so no customer's price moves as a result of this fix.
147	 *
148	 * Async because it reads a setting. Callers resolve it ONCE and pass it into
149	 * `retailCents`, which stays pure so the arithmetic is trivially checkable.
150	 */
151	export async function domainMarkupPct(): Promise<number> {
152	  const envDefault = Number(process.env.DOMAIN_MARKUP_PCT ?? DEFAULT_MARKUP_PCT);
153	  const pct = await getSettingInt("domain_markup_percent", envDefault);
154	  // Clamp: a free-text admin field that multiplies every domain price. A stray
155	  // keystroke must not be able to bill a customer 5000% of cost.
156	  return Math.min(Math.max(Number.isFinite(pct) ? pct : envDefault, 0), 500);
157	}
