159	/** Retail (customer) price for a registrar cost at `pct` markup. Pure. */
160	export function retailCents(costCents: number | null, pct: number): number | null {
161	  if (costCents === null) return null;
162	  return Math.round(costCents * (1 + pct / 100));
163	}
