313	// ---------- Inbound transfers (transfer-in) ----------
314	//
315	// name.com v4 transfers:
316	//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
317	//   GET  /v4/transfers                      -> { transfers: [...] }
318	//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
319	//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
320	//
321	// A transfer always includes a 1-year extension of the registration, which is
322	// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
323	// registration rate.
324	
325	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
326	const SANDBOX_APPROVAL_MS = 2 * 60_000;
327	const SANDBOX_REGISTRY_MS = 5 * 60_000;
328	
329	/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
330	function sandboxTldCostCents(domain: string): number {
331	  const tld = domain.slice(domain.lastIndexOf(".") + 1);
332	  let h = 0;
333	  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
334	  return 900 + (h % 21) * 50; // $9.00 – $19.00
335	}
