337	export type TransferCheck = {
338	  domain: string;
339	  /** True when we believe an inbound transfer can be submitted for this name. */
340	  transferable: boolean;
341	  /** Plain-English reason when `transferable` is false. */
342	  reason: string | null;
343	  premium: boolean;
344	  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
345	  priceCents: number | null;
346	  /** Registrar cost we pay name.com (what we send as `purchasePrice`). */
347	  costCents: number | null;
348	};
349	
350	/**
351	 * The registrar cost of transferring `domain`, in integer cents.
352	 *
353	 * Transfers are billed at the TLD's renewal rate. name.com only reliably prices
354	 * a name it can see, so we try three sources in order and give up honestly:
355	 *   1. the availability result for the domain itself,
356	 *   2. the per-domain pricing endpoint,
357	 *   3. a throwaway probe name on the same TLD — TLD pricing is per-TLD, so an
358	 *      unregistered sibling quotes the same renewal rate.
359	 */
360	async function transferCostCents(domain: string, availability: any): Promise<number | null> {
361	  const own = dollarsToCents(availability?.renewalPrice ?? availability?.purchasePrice);
362	  if (own !== null && own > 0) return own;
363	
364	  try {
365	    const p = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getPricing`);
366	    const quoted = dollarsToCents(p?.transferPrice ?? p?.renewalPrice ?? p?.purchasePrice);
367	    if (quoted !== null && quoted > 0) return quoted;
368	  } catch {
369	    /* endpoint unavailable for this TLD/account — fall through to the probe */
370	  }
371	
372	  const tld = domain.slice(domain.indexOf(".") + 1);
373	  try {
374	    const probe = `nxeon-price-probe-${Math.random().toString(36).slice(2, 10)}.${tld}`;
375	    const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [probe] });
376	    const r = (json.results ?? [])[0];
377	    const c = dollarsToCents(r?.renewalPrice ?? r?.purchasePrice);
378	    if (c !== null && c > 0) return c;
379	  } catch {
380	    /* registrar unhappy — no price, caller surfaces that plainly */
381	  }
382	  return null;
383	}
