385	/**
386	 * Can this domain be transferred in, and what would it cost? Never throws for a
387	 * "no" answer — a non-transferable name comes back with `transferable: false`
388	 * and a reason the customer can act on.
389	 */
390	export async function checkTransfer(domain: string): Promise<TransferCheck> {
391	  if (SANDBOX) {
392	    // Synthetic: everything is transferable except names containing "locked",
393	    // which exercise the rejected-quote path in staging.
394	    const cost = sandboxTldCostCents(domain);
395	    if (domain.includes("locked")) {
396	      return {
397	        domain,
398	        transferable: false,
399	        reason: "This domain is locked at its current registrar. Unlock it there and try again.",
400	        premium: false,
401	        priceCents: null,
402	        costCents: null,
403	      };
404	    }
405	    return {
406	      domain,
407	      transferable: true,
408	      reason: null,
409	      premium: false,
410	      priceCents: retailCents(cost, await domainMarkupPct()),
411	      costCents: cost,
412	    };
413	  }
414	
415	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [domain] });
416	  const r = (json.results ?? [])[0];
417	  if (!r) {
418	    return {
419	      domain,
420	      transferable: false,
421	      reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.",
422	      premium: false,
423	      priceCents: null,
424	      costCents: null,
425	    };
426	  }
427	  // Purchasable means nobody owns it — there is nothing to transfer.
428	  if (r.purchasable === true) {
429	    return {
430	      domain,
431	      transferable: false,
432	      reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.",
433	      premium: r.premium === true,
434	      priceCents: null,
435	      costCents: null,
436	    };
437	  }
438	  if (r.premium === true) {
439	    return {
440	      domain,
441	      transferable: false,
442	      reason: "Premium domains can't be transferred in automatically — contact support.",
443	      premium: true,
444	      priceCents: null,
445	      costCents: null,
446	    };
447	  }
448	
449	  const cost = await transferCostCents(domain, r);
450	  if (cost === null) {
451	    return {
452	      domain,
453	      transferable: false,
454	      reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.",
455	      premium: false,
456	      priceCents: null,
457	      costCents: null,
458	    };
459	  }
460	  return {
461	    domain,
462	    transferable: true,
463	    reason: null,
464	    premium: false,
465	    priceCents: retailCents(cost, await domainMarkupPct()),
466	    costCents: cost,
467	  };
468	}
