478	/**
479	 * Submit an inbound transfer. `purchaseCents` is the registrar COST (integer
480	 * cents) — the same "what we expect to pay" contract `registerDomain` uses.
481	 * The auth code is passed straight through and never logged.
482	 */
483	export async function createTransfer(
484	  domain: string,
485	  authCode: string,
486	  purchaseCents: number
487	): Promise<TransferInfo> {
488	  if (SANDBOX) {
489	    // Names containing "fail" reject at submit time so staging can exercise the
490	    // "registrar refused, customer not charged" path.
491	    if (domain.includes("fail")) throw new RegistrarError("namecom", "transfer rejected by the registry (sandbox)");
492	    return { domain, status: "pendingOwnerApproval", email: `owner@${domain}` };
493	  }
494	  const json = await nc("POST", "/v4/transfers", {
495	    domainName: domain,
496	    authCode,
497	    privacyEnabled: true,
498	    purchasePrice: purchaseCents / 100,
499	  });
500	  const t = json?.transfer ?? json ?? {};
501	  return {
502	    domain: t.domainName ?? domain,
503	    status: String(t.status ?? "pending"),
504	    email: t.email ? String(t.email) : null,
505	  };
506	}
