508	/**
509	 * Current state of an inbound transfer. Returns null when the registrar has no
510	 * transfer for this domain — which is a NORMAL answer once a transfer settles
511	 * and drops off the list, so callers must resolve that against `domainInfo`
512	 * rather than treating it as a failure.
513	 *
514	 * `startedAt` is only read in SANDBOX, where it drives a synthetic progression
515	 * (registrar.ts holds no state of its own).
516	 */
517	export async function getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null> {
518	  if (SANDBOX) {
519	    const age = Date.now() - (startedAt?.getTime() ?? Date.now());
520	    const status =
521	      age < SANDBOX_APPROVAL_MS
522	        ? "pendingOwnerApproval"
523	        : age < SANDBOX_REGISTRY_MS
524	          ? "pendingRegistry"
525	          : "completed";
526	    return { domain, status, email: `owner@${domain}` };
527	  }
528	  const t = await nc("GET", `/v4/transfers/${encodeURIComponent(domain)}`, undefined, { nullOn404: true });
529	  if (!t) return null;
530	  return {
531	    domain: t.domainName ?? domain,
532	    status: String(t.status ?? "pending"),
533	    email: t.email ? String(t.email) : null,
534	  };
535	}
