537	/**
538	 * Ask the registrar to cancel an in-flight inbound transfer. Throws if the
539	 * registrar refuses (e.g. the transfer already completed at the registry) —
540	 * callers must NOT credit the customer unless this resolves.
541	 */
542	export async function cancelTransfer(domain: string): Promise<TransferInfo> {
543	  if (SANDBOX) return { domain, status: "cancelled", email: null };
544	  const t = await nc("POST", `/v4/transfers/${encodeURIComponent(domain)}:cancel`, {});
545	  return {
546	    domain: t?.domainName ?? domain,
547	    status: String(t?.status ?? "cancelled"),
548	    email: t?.email ? String(t.email) : null,
549	  };
550	}
