563	/** Bucket a raw registrar transfer status into something we can act on. */
564	export function transferOutcome(status: string): "completed" | "failed" | "pending" {
565	  const s = status.toLowerCase();
566	  if (/(complete|success|transferred)/.test(s)) return "completed";
567	  if (/(cancel|reject|denied|fail|expired|refund|void)/.test(s)) return "failed";
568	  return "pending";
569	}
570	
571	/** Human label for a raw registrar transfer status. */
572	export function transferStatusLabel(status: string): string {
573	  const s = status.toLowerCase();
574	  if (/owner|admin|approval|contact/.test(s)) return "Waiting for you to approve the confirmation email";
575	  if (/registry|processing|progress/.test(s)) return "Submitted to the registry";
576	  if (/complete|success|transferred/.test(s)) return "Completed";
577	  if (/cancel/.test(s)) return "Cancelled";
578	  if (/reject|denied/.test(s)) return "Rejected by the losing registrar";
579	  if (/expired/.test(s)) return "Expired — the confirmation was never approved";
580	  return status;
581	}
