// GoGetSSL API client (reseller aggregator for RapidSSL/Sectigo/DigiCert/etc.).
//
// Plain server-side module (NO "use server") — safe to import from server
// actions and the worker; never bundled to the client.
//
// UNTESTED AGAINST A LIVE ACCOUNT as of 2026-09-09: this codebase has no
// GoGetSSL credentials yet. Endpoints, auth flow, and the addSSLOrder/
// getOrderStatus field names below are sourced from GoGetSSL's own published
// API guide + sample clients (github.com/gogetssl/api, doc-v1.gogetssl.com),
// not guessed — but a few response field names (marked below) could not be
// confirmed byte-for-byte and should be checked against a real sandbox order
// before this ever issues a real certificate. Everything that calls this
// module is gated behind ENABLE_PAID_SSL + real credentials (see worker/ssl.ts)
// so it fails loudly rather than silently misbehaving until that
// verification happens.
//
// Confirmed live (not guessed) from the source of an actual maintained
// client (github.com/Dexus/node-gogetssl):
//   base URL   https://sandbox.gogetssl.com/api  (prod: https://my.gogetssl.com/api)
//   POST /auth/            { user, pass }                    -> { key }
//   (every call after auth includes auth_key: <key>)
//   GET  /products/                                          -> product list
//   POST /orders/add_ssl_order/                               -> order created
//   GET  /orders/status/{orderId}                              -> order status

const SANDBOX_BASE = "https://sandbox.gogetssl.com/api";
const PROD_BASE = "https://my.gogetssl.com/api";

export class GoGetSslError extends Error {
  constructor(
    message: string,
    public status?: number,
    public body?: unknown,
  ) {
    super(message);
    this.name = "GoGetSslError";
  }
}

function baseUrl(): string {
  // Same "sandbox until proven" caution as the rest of this module — never
  // default to the production endpoint just because credentials exist.
  return process.env.GOGETSSL_ENV === "production" ? PROD_BASE : SANDBOX_BASE;
}

function credentials(): { user: string; pass: string } | null {
  const user = process.env.GOGETSSL_API_USER;
  const pass = process.env.GOGETSSL_API_PASS;
  if (!user || !pass) return null;
  return { user, pass };
}

/** True only when real credentials are configured — the single gate every
 * caller (worker/ssl.ts) should check before attempting a real order. */
export function goGetSslConfigured(): boolean {
  return credentials() !== null;
}

async function rawRequest<T>(method: "GET" | "POST", path: string, body?: Record<string, unknown>): Promise<T> {
  const url = `${baseUrl()}${path.startsWith("/") ? path : `/${path}`}`;
  const res = await fetch(url, {
    method,
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: body ? new URLSearchParams(body as Record<string, string>).toString() : undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let parsed: any;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new GoGetSslError(`GoGetSSL returned non-JSON (HTTP ${res.status}): ${text.slice(0, 200)}`, res.status);
  }
  if (!res.ok) {
    throw new GoGetSslError(parsed?.message ?? parsed?.description ?? `GoGetSSL HTTP ${res.status}`, res.status, parsed);
  }
  return parsed as T;
}

let cachedKey: { key: string; fetchedAt: number } | null = null;

